// Process Kanboard tasks to find Due Diligence tasks
const tasks = $input.first().json.result || [];
console.log(`Found ${tasks.length} total tasks`);

const dueDiligenceTasks = [];

for (const task of tasks) {
  const title = task.title ? task.title.toString().trim() : '';
  const description = task.description ? task.description.toString().trim() : '';

  console.log(`Checking task: "${title}"`);

  // Check if task title contains "Due Diligence:" pattern with quotes
  const ddPattern = /Due Diligence:\s*["']([^"']+)["']/i;
  const match = title.match(ddPattern);

  if (match) {
    // Extract company name from quotes
    const companyName = match[1].trim();

    // Extract website from description (look for URLs)
    const urlRegex = /https?:\/\/(www\.)?[-a-zA-Z0-9@:%._\+~#=]{1,256}\.[a-zA-Z0-9()]{1,6}\b([-a-zA-Z0-9()@:%_\+.~#?&//=]*)/g;
    const urls = description.match(urlRegex) || [];
    const website = urls.length > 0 ? urls[0] : '';

    console.log(`✅ Found Due Diligence task: "${companyName}" (ID: ${task.id})`);
    console.log(`   Website: ${website || 'Not found'}`);

    dueDiligenceTasks.push({
      json: {
        task_id: task.id,
        title: title,
        company_name: companyName,
        website: website,
        description: description,
        project_id: task.project_id || 1,
        has_attachments: false,
        attachment_count: 0
      }
    });
  }
}

if (dueDiligenceTasks.length === 0) {
  console.log('ℹ️ No Due Diligence tasks found');
  return [{ json: { message: 'No Due Diligence tasks found' } }];
}

console.log(`📋 Processing ${dueDiligenceTasks.length} Due Diligence tasks`);
return dueDiligenceTasks;

// Process attachments and combine with task data
const taskData = $input.first().json;
const attachments = $input.last().json.result || [];

// Filter for PDF attachments
const pdfAttachments = attachments.filter(file => {
  const fileName = file.name ? file.name.toLowerCase() : '';
  return fileName.endsWith('.pdf');
});

console.log(`📎 Task ${taskData.task_id} has ${attachments.length} total attachments, ${pdfAttachments.length} PDFs`);

// Log attachment details
if (pdfAttachments.length > 0) {
  pdfAttachments.forEach(pdf => {
    console.log(`   📄 PDF: ${pdf.name} (ID: ${pdf.id}, Size: ${pdf.size} bytes)`);
  });
}

return [{
  json: {
    ...taskData,
    has_attachments: attachments.length > 0,
    attachment_count: attachments.length,
    pdf_count: pdfAttachments.length,
    attachments: attachments,
    pdf_attachments: pdfAttachments
  }
}];

// Generate summary report for tasks without PDFs
const taskData = $input.first().json;

const summary = {
  task_info: {
    task_id: taskData.task_id,
    title: taskData.title,
    company_name: taskData.company_name,
    website: taskData.website || 'Not specified',
    project_id: taskData.project_id
  },
  attachments: {
    total_files: taskData.attachment_count,
    pdf_files: taskData.pdf_count,
    has_pdfs: false
  },
  status: 'No PDFs found - manual review required'
};

console.log(`\n=== DUE DILIGENCE TASK SUMMARY (NO PDFs) ===`);
console.log(`Company: ${summary.task_info.company_name}`);
console.log(`Website: ${summary.task_info.website}`);
console.log(`Status: No PDF documents found`);
console.log(`=============================================\n`);

return [{ json: summary }];

// Process each PDF and create extraction tasks
const taskData = $input.first().json;
const pdfAttachments = taskData.pdf_attachments || [];

if (pdfAttachments.length === 0) {
  console.log('📄 No PDF attachments found');
  return [{ json: { no_pdfs: true } }];
}

console.log(`📄 Processing ${pdfAttachments.length} PDF files`);

// For each PDF, we'll create a summary without text extraction
// since we can't use PyPDF2 in n8n environment
const pdfSummaries = pdfAttachments.map((pdf, index) => {
  const downloadUrl = `http://localhost:8000/?controller=TaskFileController&action=download&file_id=${pdf.id}&project_id=${taskData.project_id}`;

  return {
    json: {
      file_name: pdf.name,
      file_id: pdf.id,
      size_bytes: pdf.size,
      download_url: downloadUrl,
      task_id: taskData.task_id,
      project_id: taskData.project_id,
      company_name: taskData.company_name,
      website: taskData.website,
      extracted_text: `PDF Document Analysis Required\n\nFile: ${pdf.name}\nSize: ${pdf.size} bytes\nCompany: ${taskData.company_name}\nWebsite: ${taskData.website}\n\nThis PDF document requires manual review or external processing for text extraction. Download URL: ${downloadUrl}\n\nProcessing timestamp: ${new Date().toISOString()}`,
      extraction_method: 'manual_review_required',
      extraction_success: true
    }
  };
});

return pdfSummaries;
